import {
  Mesh,
  PlaneGeometry,
  Object3D,
  Float32BufferAttribute,
  Texture,
  Color,
} from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  color,
  texture,
} from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as textUtils from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [id]
 * @property {Object} position
 * @property {Object} rotation
 * @property {Object} scale
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 * @property {string} textContent
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} textureLoader
 * @property {Object} glbLoader
 * @property {Object} primitives
 * @property {Object} fontAtlas
 */

/**
 * Creates a journal card label node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // -----------------------------------------------------------------------
  // Geometry & sizing
  // -----------------------------------------------------------------------
  // Main background plane – aspect derived from source rect (512x320)
  const BACKGROUND_ASPECT = 512 / 320; // 1.6
  const bgWidth = 1.6; // arbitrary scene units preserving aspect
  const bgHeight = bgWidth / BACKGROUND_ASPECT;

  const bgGeometry = new PlaneGeometry(bgWidth, bgHeight);

  // -----------------------------------------------------------------------
  // Background material (brushed metal)
  // -----------------------------------------------------------------------
  const metalTex = ctx.textureLoader.load(
    '/prism-assets/chrome/brushed-metal.map.png'
  );

  const bgMaterial = new MeshBasicNodeMaterial();
  bgMaterial.map = metalTex;
  // surface colour as a subtle tint
  bgMaterial.color = color('#0b0b10');

  const bgMesh = new Mesh(bgGeometry, bgMaterial);
  bgMesh.position.set(
    config.position?.x ?? -3.2,
    config.position?.y ?? 1,
    config.position?.z ?? 0.06
  );
  bgMesh.rotation.set(
    config.rotation?.x ?? 0,
    config.rotation?.y ?? 0,
    config.rotation?.z ?? 0
  );
  bgMesh.scale.set(
    config.scale?.x ?? 1,
    config.scale?.y ?? 1,
    config.scale?.z ?? 1
  );

  // -----------------------------------------------------------------------
  // Text rendering via font atlas
  // -----------------------------------------------------------------------
  const atlas = ctx.fontAtlas; // assumed to expose texture, width, height, and region helpers
  const atlasTex = atlas.texture instanceof Texture ? atlas.texture : null;

  // Atlas region for the label (0,0,512,320)
  const region = { x: 0, y: 0, width: 512, height: 320 };

  // Compute UVs for the region
  const texW = atlas.width || 1024; // fallback if not provided
  const texH = atlas.height || 1024;
  const u0 = region.x / texW;
  const v0 = region.y / texH;
  const u1 = (region.x + region.width) / texW;
  const v1 = (region.y + region.height) / texH;

  // Text plane geometry – same aspect as region
  const txtWidth = bgWidth;
  const txtHeight = bgHeight;
  const txtGeometry = new PlaneGeometry(txtWidth, txtHeight);
  // Override UVs to sample only the region
  const uvArray = new Float32Array([
    u0, v1, // bottom‑left
    u1, v1, // bottom‑right
    u1, v0, // top‑right
    u0, v0, // top‑left
  ]);
  txtGeometry.setAttribute('uv', new Float32BufferAttribute(uvArray, 2));

  const txtMaterial = new MeshBasicNodeMaterial();
  txtMaterial.map = atlasTex;
  txtMaterial.transparent = true;
  txtMaterial.depthWrite = false;
  txtMaterial.color = color('#16161d'); // ink colour

  const txtMesh = new Mesh(txtGeometry, txtMaterial);
  // Slightly in front of background to avoid Z‑fighting
  txtMesh.position.set(0, 0, 0.001);

  // Assemble hierarchy
  bgMesh.add(txtMesh);

  // -----------------------------------------------------------------------
  // Apply cinematic primitives (none in this spec but kept for completeness)
  // -----------------------------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(bgMesh, prim.params);
      }
    }
  }

  // -----------------------------------------------------------------------
  // User data – handlers placeholder and cleanup
  // -----------------------------------------------------------------------
  const root = new Object3D();
  root.add(bgMesh);
  root.userData = {
    handlers: {},
    cleanup() {
      // Dispose geometries and materials
      bgGeometry.dispose();
      txtGeometry.dispose();
      bgMaterial.dispose();
      txtMaterial.dispose();
      // No GSAP timelines created for this node, but kill any if present
      if (this._gsapTimeline) {
        this._gsapTimeline.kill();
      }
    },
  };

  return root;
}
